// NEVER DO THIS - Plaintext Storage
public class InsecureUserService {
    public void register(String email, String password) {
        var user = new User(email, password); // storing raw password
        userRepository.save(user);
    }
}

// CORRECT - Hashed Storage with BCrypt
@Service
public class UserService {
    private final UserRepository userRepository;
    private final PasswordEncoder passwordEncoder;

    public void register(String email, String rawPassword) {
        var hashedPassword = passwordEncoder.encode(rawPassword); // one-way hash
        var user = new User(email, hashedPassword);
        userRepository.save(user);
    }

    public boolean authenticate(String email, String inputPassword) {
        var user = userRepository.findByEmail(email);
        return passwordEncoder.matches(inputPassword, user.getPassword()); // constant-time comparison
    }
}

// Manual salt generation (educational - bcrypt does this automatically)
public class PasswordHashingExample {
    public String hashPasswordWithSalt(String password) {
        var secureRandom = new SecureRandom();
        var salt = new byte[16]; // 128-bit salt
        secureRandom.nextBytes(salt); // cryptographically random

        var saltedPassword = password + Base64.getEncoder().encodeToString(salt);
        var hash = SHA256.hash(saltedPassword); // hypothetical

        // Store both: salt + hash, often concatenated
        return Base64.getEncoder().encodeToString(salt) + ":" + hash;
    }
}

// Automatic salt handling with BCrypt (production approach)
@Service
public class UserService {
    private final PasswordEncoder passwordEncoder;

    public void register(String email, String password) {
        var hash = passwordEncoder.encode(password);
        // bcrypt output: $2a$12$R9h/cIPz0gi.URNNX3kh2O PST9/PgBkqquzi.Ss7KIUgO2t0jWMUW
        //                         ^^^^^^^^^^^^^^^^^^^^^^ = 22-char salt (embedded)
        userRepository.save(new User(email, hash)); // salt already in hash string
    }
}

@Configuration
@EnableWebSecurity
public class SecurityConfig {
    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder(12); // cost factor 12 for production
    }

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
        return http
            .authorizeHttpRequests(auth -> auth
                .requestMatchers("/api/register").permitAll()
                .anyRequest().authenticated())
            .build();
    }
}

@Service
public class UserService {
    private final UserRepository userRepository;
    private final PasswordEncoder passwordEncoder; // injected bean

    public UserService(UserRepository repo, PasswordEncoder encoder) {
        this.userRepository = repo;
        this.passwordEncoder = encoder;
    }

    public void registerUser(String email, String rawPassword) {
        var hashedPassword = passwordEncoder.encode(rawPassword); // salt + hash
        var user = new User(email, hashedPassword);
        userRepository.save(user);
    }

    public boolean authenticate(String email, String inputPassword) {
        var user = userRepository.findByEmail(email)
            .orElseThrow(() -> new UsernameNotFoundException("User not found"));
        return passwordEncoder.matches(inputPassword, user.getPassword()); // constant-time check
    }
}

