@Service
public class UserService {
    private final PasswordEncoder passwordEncoder;

    public void registerUser(String email, String rawPassword) {
        var hashedPassword = passwordEncoder.encode(rawPassword);
        // Output example: $2a$12$R9h/cIPz0gi.URNNX3kh2OPST9/PgBkqquzi.Ss7KIUgO2t0jWMUW
        // Format: $2a$ (version) $12$ (cost) $salt (22 chars) $hash (31 chars)
        var user = new User(email, hashedPassword);
        userRepository.save(user);
    }

    public boolean verifyPassword(String inputPassword, String storedHash) {
        return passwordEncoder.matches(inputPassword, storedHash); // constant-time comparison
    }
