import org.springframework.security.crypto.argon2.Argon2PasswordEncoder;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.crypto.password.Pbkdf2PasswordEncoder;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration
public class PasswordHashingConfig {

    // First choice: Argon2id, OWASP minimums
    // args: saltLen=16, hashLen=32, parallelism=1, memory=19456 KiB (19 MiB), iterations=2
    @Bean
    public PasswordEncoder passwordEncoder() {
        return new Argon2PasswordEncoder(16, 32, 1, 19456, 2);
    }

    // Fallbacks you might declare when Argon2 is unavailable or compliance is required:
    public PasswordEncoder bcryptFallback() {
        return new BCryptPasswordEncoder(12); // cost factor 12
    }

    public PasswordEncoder pbkdf2ForFips() {
        // secret, saltLength, iterations=600_000, SHA-256
        return new Pbkdf2PasswordEncoder("", 16, 600_000,
                Pbkdf2PasswordEncoder.SecretKeyFactoryAlgorithm.PBKDF2WithHmacSHA256);
    }
}
```
The same `encoder.encode()` / `encoder.matches()` API works for every algorithm, so swapping the bean is the only change needed.
